            sum_a -= max(a) - min(b)
            a.remove(max(a))
            b.remove(min(b))
        elif sum_b > sum_a:
            sum_b -= max(b) - min(a)
            a.remove(min(a))
            b.remove(max(b))
        else:
            a.remove(min(a))
            b.remove(max(b))

