from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        q = deque()
        for i in range(n):
            if arr[i] == 0:
                q.append(i)
        for i in range(n):
            if arr[i]!= 0:
                if not q or q[0]!= i - arr[i]:
                    print("NO")
                    break
                else:
                    for _ in range(arr[i]):
                        q.popleft()
            else:
                q.append(i)
        else:
            print("YES")

