        for i in range(m):
            if pq[0][0] < m + 1 - pq[0][1]:
                s[pq[0][1] - 1] = 'A'
                heapq.heappop(pq)
            else:
                s[pq[0][0] - 1] = 'A'
                heapq.heappop(pq)
        print(''.join(s))

